module asyn_fifo#(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output reg [WIDTH-1:0] rdata,
    output reg wfull,
    output reg rempty
);
parameter
ADDR_WIDTH = $clog2(DEPTH);
input
wire [ADDR_WIDTH:0] waddr;
wire [ADDR_WIDTH:0] raddr;
reg [ADDR_WIDTH:0] waddr_bin;
reg [ADDR_WIDTH:0] raddr_bin;
wire [ADDR_WIDTH:0] waddr_gray;
wire [ADDR_WIDTH:0] raddr_gray;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
wire wen;
wire ren;
wire wfull;
wire rempty;
reg [WIDTH-1:0] rdata;
reg [WIDTH-1:0] wdata;
reg [ADDR_WIDTH:0] wptr;
reg [ADDR_WIDTH:0] rptr;
reg [ADDR_WIDTH:0] wptr_buff;
reg [ADDR_WIDTH:0] rptr_buff;
wire wen;
wire ren;
wire wfull;
wire rempty;

// RAM instance
dual_port_RAM#(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
)ram_inst(
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr),
    .rdata(rdata)
);

// Write pointer logic
always@(posedge wclk or negedge wrstn)begin
    if(!wrstn)begin
        waddr_bin <= 'd0;
    end
    else if(!wfull && winc)begin
        waddr_bin <= waddr_bin + 1'd1;
    end
end
always@(posedge wclk or negedge wrstn)begin
    if(!wrstn)begin
        waddr_gray <= 'd0;
    end
    else begin
        waddr_gray <= waddr_bin ^ (waddr_bin>>1);
    end
end
always@(posedge wclk or negedge wrstn)begin
    if(!wrstn)begin
        wptr <= 'd0;
    end
    else begin
        wptr <= waddr_gray;
    end
end

// Read pointer logic
always@(posedge rclk or negedge rrstn)begin
    if(!rrstn)begin
        raddr_bin <= 'd0;
    end
    else if(!rempty && rinc)begin
        raddr_bin <= raddr_bin + 1'd1;
    end
end
always@(posedge rclk or negedge rrstn)begin
    if(!rrstn)begin
        raddr_gray <= 'd0;
    end
    else begin
        raddr_gray <= raddr_bin ^ (raddr_bin>>1);
    end
end
always@(posedge rclk or negedge rrstn)begin
    if(!rrstn)begin
        rptr <= 'd0;
    end
    else begin
        rptr <= raddr_gray;
    end
end

// Read pointer buffer logic
always@(posedge wclk or negedge wrstn)begin
    if(!wrstn)begin
        rptr_buff <= 'd0;
    end
    else begin
        rptr_buff <= rptr;
    end
end

// Write pointer buffer logic
always@(posedge rclk or negedge rrstn)begin
    if(!rrstn)begin
        wptr_buff <= 'd0;
    end
    else begin
        wptr_buff <= wptr;
    end
end

// Full and empty flags
assign wfull = (wptr == rptr_buff)? 1'd1 : 1'd0;
assign rempty = (rptr == wptr_syn)? 1'd1 : 1'd0;

// Read and write enable signals
assign wen = !wfull && winc;
assign ren = !rempty && rinc;

endmodule
